export default function StaffPage() {
    const [staff, setStaff] = useState<StaffMemberDTO[]>([]);
    const [loading, setLoading] = useState(true);
    const [dialogOpen, setDialogOpen] = useState(false);

    useEffect(() => {
        fetchStaff();
