import { NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { classifyConversationIntent } from "@/lib/gemini";

/** POST /api/ai/classify
 *  Classifies the intent of an incoming message for inbox triage
 */
export async function POST(req: Request) {
    const user = await getCurrentUser();
    if (!user?.workspaceId) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { message, history } = await req.json();
    if (!message) {
        return NextResponse.json({ error: "Message is required" }, { status: 400 });
    }

    try {
        const result = await classifyConversationIntent(message, history);
        return NextResponse.json(result);
    } catch (error) {
        console.error("Intent classification error:", error);
        return NextResponse.json({ error: "Classification failed" }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { generateDashboardInsights } from "@/lib/gemini";

export async function GET() {
  const user = await getCurrentUser();
  if (!user || !user.workspaceId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const wid = user.workspaceId;
  const weekAgo = new Date();
  weekAgo.setDate(weekAgo.getDate() - 7);

  const [
    totalBookings,
    completedBookings,
    newContacts,
    pendingForms,
    allInventory,
    unreadMessages,
  ] = await Promise.all([
    prisma.booking.count({ where: { workspaceId: wid } }),
    prisma.booking.count({
      where: { workspaceId: wid, status: "COMPLETED" },
    }),
    prisma.contact.count({
      where: { workspaceId: wid, createdAt: { gte: weekAgo } },
    }),
    prisma.formSubmission.count({
      where: { workspaceId: wid, status: { in: ["PENDING", "SENT"] } },
    }),
    prisma.inventoryItem.findMany({ where: { workspaceId: wid } }),
    prisma.conversation.count({
      where: { workspaceId: wid, unreadCount: { gt: 0 } },
    }),
  ]);

  const lowStockItems = allInventory.filter(
    (item: any) => item.quantity <= item.threshold
  ).length;

  const insights = await generateDashboardInsights({
    totalBookings,
    completedBookings,
    newContacts,
    pendingForms,
    lowStockItems,
    unreadMessages,
  });

  return NextResponse.json({ insights });
}

