import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { hashPassword, createToken, setAuthCookie } from "@/lib/auth";

export async function POST(req: Request) {
  try {
    const { email, password, name } = await req.json();

    if (!email || !password || !name) {
      return NextResponse.json(
        { error: "Missing required fields" },
        { status: 400 }
      );
    }

    const existingUser = await prisma.user.findUnique({ where: { email } });
    if (existingUser) {
      return NextResponse.json(
        { error: "Email already registered" },
        { status: 409 }
      );
    }

    const passwordHash = await hashPassword(password);

    const workspace = await prisma.workspace.create({
      data: { name: `${name}'s Workspace`, status: "ONBOARDING" },
    });

    const user = await prisma.user.create({
      data: {
        email,
        name,
        passwordHash,
        role: "OWNER",
        workspaceId: workspace.id,
      },
    });

    // Generate and store OTP
    const { generateOTP, storeOTP } = await import("@/lib/otp");
    const otp = generateOTP();
    await storeOTP(user.id, otp);

    // Send OTP Email
    const { sendEmail, buildEmailTemplate } = await import("@/lib/email");
    await sendEmail({
      to: email,
      subject: "Verify your email - CareOps",
      html: buildEmailTemplate(
        "Verify your email",
        `<p>Your verification code is:</p><h1>${otp}</h1><p>This code expires in 15 minutes.</p>`
      ),
    });

    return NextResponse.json({
      message: "Registration successful. Please check your email for the verification code.",
      userId: user.id
    });
  } catch (error) {
    console.error("Register error:", error);
    return NextResponse.json(
      { error: "Registration failed" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { generateOTP, storeOTP } from "@/lib/otp";
import { sendEmail, buildEmailTemplate } from "@/lib/email";
import { sendOTP as twilioSendOTP, sendWhatsAppOTP as twilioSendWhatsAppOTP, isConfigured as isTwilioConfigured } from "@/lib/twilio";
import { sendSMS, buildOTPMessage } from "@/lib/sms";
import { isAvailable as isWhatsAppAvailable } from "@/lib/whatsapp";

export async function POST(req: Request) {
  try {
    const { email, channel, phone } = await req.json();

    if (!email) {
      return NextResponse.json(
        { error: "Email is required" },
        { status: 400 }
      );
    }

    const user = await prisma.user.findUnique({ where: { email } });

    if (!user) {
      // Don't reveal whether user exists
      return NextResponse.json({
        message: "If an account exists, a new code has been sent.",
      });
    }

    if (user.emailVerified) {
      return NextResponse.json(
        { error: "Email is already verified" },
        { status: 400 }
      );
    }

    // Rate limit: don't resend if last OTP was less than 60 seconds ago
    if (user.otpExpires) {
      const lastSent = new Date(user.otpExpires.getTime() - 15 * 60 * 1000);
      const secondsSinceSent = (Date.now() - lastSent.getTime()) / 1000;
      if (secondsSinceSent < 60) {
        return NextResponse.json(
          { error: "Please wait before requesting a new code", retryAfter: Math.ceil(60 - secondsSinceSent) },
          { status: 429 }
        );
      }
    }

    // Determine the delivery channel
    const deliveryChannel = channel || user.otpChannel || "email";
    const otp = generateOTP();
    await storeOTP(user.id, otp);

    // Track channel
    await prisma.user.update({
      where: { id: user.id },
      data: { otpChannel: deliveryChannel },
    });

    switch (deliveryChannel) {
      case "sms": {
        const userPhone = phone || user.phone;
        if (!userPhone) {
          return NextResponse.json(
            { error: "Phone number is required for SMS verification" },
            { status: 400 }
          );
        }

        // Try MSG91's resend API first (if an OTP session already exists)
        if (isTwilioConfigured()) {
          const result = await twilioSendOTP(userPhone, otp);
          if (result.success) {
            return NextResponse.json({
              message: "A new code has been sent via SMS.",
              channel: "sms",
            });
          }
        }

        return NextResponse.json(
          { error: "Failed to send SMS. Please try email verification." },
          { status: 500 }
        );
      }

      case "whatsapp": {
        const userPhone = phone || user.phone;
        if (!userPhone) {
          return NextResponse.json(
            { error: "Phone number is required for WhatsApp verification" },
            { status: 400 }
          );
        }

        if (!isWhatsAppAvailable()) {
          return NextResponse.json(
            { error: "WhatsApp is not available. Please use SMS or email." },
            { status: 503 }
          );
        }

        const result = await twilioSendWhatsAppOTP(userPhone, otp);
        if (result.success) {
          return NextResponse.json({
            message: "A new code has been sent via WhatsApp.",
            channel: "whatsapp",
          });
        }

        return NextResponse.json(
          { error: "Failed to send WhatsApp message. Please try SMS or email." },
          { status: 500 }
        );
      }

      case "email":
      default: {
        await sendEmail({
          to: email,
          subject: "Your new verification code - CareOps",
          html: buildEmailTemplate(
            "Verify your email",
            `<p>Your new verification code is:</p><h1 style="font-size:36px;letter-spacing:8px;text-align:center;color:#2563eb;">${otp}</h1><p>This code expires in 15 minutes.</p>`
          ),
        });

        return NextResponse.json({
          message: "If an account exists, a new code has been sent.",
          channel: "email",
        });
      }
    }
  } catch (error) {
    console.error("Resend OTP error:", error);
    return NextResponse.json(
      { error: "Failed to resend code" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { generateOTP, storeOTP } from "@/lib/otp";
import { isConfigured as isTwilioConfigured, sendOTP as twilioSendOTP } from "@/lib/twilio";
import { sendSMS, buildOTPMessage } from "@/lib/sms";

export async function POST(req: Request) {
  try {
    const { email, phone } = await req.json();

    if (!email || !phone) {
      return NextResponse.json(
        { error: "Email and phone number are required" },
        { status: 400 }
      );
    }

    // Validate phone format (E.164)
    const phoneRegex = /^\+[1-9]\d{1,14}$/;
    if (!phoneRegex.test(phone)) {
      return NextResponse.json(
        { error: "Invalid phone number. Use E.164 format (e.g., +919876543210)" },
        { status: 400 }
      );
    }

    const user = await prisma.user.findUnique({ where: { email } });
    if (!user) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    // Rate limit check
    if (user.otpExpires) {
      const lastSent = new Date(user.otpExpires.getTime() - 15 * 60 * 1000);
      const secondsSinceSent = (Date.now() - lastSent.getTime()) / 1000;
      if (secondsSinceSent < 60) {
        return NextResponse.json(
          { error: "Please wait before requesting a new code", retryAfter: Math.ceil(60 - secondsSinceSent) },
          { status: 429 }
        );
      }
    }

    // Store phone on user record
    await prisma.user.update({
      where: { id: user.id },
      data: { phone },
    });

    const otp = generateOTP();
    await storeOTP(user.id, otp);
    await prisma.user.update({
      where: { id: user.id },
      data: { otpChannel: "sms" },
    });

    if (isTwilioConfigured()) {
      const result = await twilioSendOTP(phone, otp);

      if (result.success) {
        return NextResponse.json({
          message: "Verification code sent via SMS",
          channel: "sms",
          requestId: result.requestId,
        });
      }

      console.error("[send-sms-otp] Twilio delivery failed:", result.error);
      return NextResponse.json(
        { error: `Failed to send SMS: ${result.error}` },
        { status: 500 }
      );
    }

    // In dev mode, if Twilio is not configured, still return the OTP for testing
    console.log(`[DEV] SMS OTP for ${email}: ${otp}`);

    return NextResponse.json({
      message: "Verification code sent via SMS (Mocked)",
      channel: "sms",
      ...(process.env.NODE_ENV !== "production" && { devOtp: otp }),
    });
  } catch (error) {
    console.error("Send SMS OTP error:", error);
    return NextResponse.json(
      { error: "Failed to send SMS OTP" },
      { status: 500 }
    );
  }
}

