import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { addMinutes } from "date-fns";
import { triggerAutomation } from "@/lib/automation";
import { syncBookingToCalendar } from "@/lib/google-calendar";
import { parseLocalDateTime } from "@/lib/date-utils";
import { checkRateLimit, RATE_LIMITS, getClientIP } from "@/lib/rate-limiter";

export async function POST(req: Request) {
    try {
        // Rate limiting check
        const clientIP = getClientIP(req);
        const identifier = `${clientIP}:booking`;
        const rateLimit = checkRateLimit(identifier, RATE_LIMITS.BOOKING);

        if (!rateLimit.allowed) {
            return NextResponse.json(
                { 
                    error: "Rate limit exceeded",
                    message: "Too many booking attempts. Please try again later.",
                    retryAfter: Math.ceil((rateLimit.resetTime - Date.now()) / 1000)
                },
                { 
                    status: 429,
                    headers: {
                        'X-RateLimit-Limit': String(RATE_LIMITS.BOOKING.maxRequests),
                        'X-RateLimit-Remaining': String(rateLimit.remaining),
                        'X-RateLimit-Reset': String(rateLimit.resetTime),
                        'Retry-After': String(Math.ceil((rateLimit.resetTime - Date.now()) / 1000))
                    }
                }
            );
        }

        const body = await req.json();
        const { serviceId, date, time, contact, notes } = body;

        if (!serviceId || !date || !time || !contact?.email || !contact?.name) {
            return NextResponse.json({ error: "Missing required fields" }, { status: 400 });
        }

        // 1. Fetch Service details (outside transaction - read-only)
        const service = await prisma.service.findUnique({
            where: { id: serviceId },
        });

        if (!service) {
            return NextResponse.json({ error: "Service not found" }, { status: 404 });
        }

        // Fetch workspace timezone
        const workspace = await prisma.workspace.findUnique({
            where: { id: service.workspaceId },
            select: { timezone: true }
        });

        const timezone = workspace?.timezone || "UTC";

        // Convert local date/time to UTC for storage
        const bookingStart = parseLocalDateTime(date, time, timezone);
        const bookingEnd = addMinutes(bookingStart, service.duration);

        // 2. CRITICAL FIX: Use transaction with Serializable isolation to prevent race conditions
        // This ensures conflict check and booking creation are atomic
        const result = await prisma.$transaction(async (tx) => {
            // 2a. Validate availability (within transaction - prevents race conditions)
            const existingConflict = await tx.booking.findFirst({
                where: {
                    workspaceId: service.workspaceId,
                    status: { not: "CANCELLED" },
                    AND: [
                        { date: { lt: bookingEnd } },
                        { endTime: { gt: bookingStart } }
                    ]
                }
            });

            if (existingConflict) {
                throw new Error("CONFLICT: Slot no longer available");
            }

            // 2b. Check inventory availability (within transaction)
            const inventoryLinks = await tx.serviceInventoryLink.findMany({
                where: { serviceId },
                include: { inventory: true }
            });

            for (const link of inventoryLinks) {
                if (link.inventory.quantity < link.quantity) {
                    throw new Error(`INVENTORY:Insufficient inventory for ${link.inventory.name}`);
                }
            }

            // 2c. Find or Create Contact (within transaction)
            let dbContact = await tx.contact.findFirst({
                where: {
                    email: contact.email,
                    workspaceId: service.workspaceId
                }
            });

            if (dbContact) {
                dbContact = await tx.contact.update({
                    where: { id: dbContact.id },
                    data: {
                        name: contact.name,
                        phone: contact.phone || dbContact.phone,
                        notes: notes ? (dbContact.notes ? `${dbContact.notes}\n${notes}` : notes) : dbContact.notes
                    }
                });
            } else {
                dbContact = await tx.contact.create({
                    data: {
                        name: contact.name,
                        email: contact.email,
                        phone: contact.phone,
                        notes: notes,
                        workspaceId: service.workspaceId,
                        source: "booking_page"
                    }
                });
            }

            // 2d. Create Booking (within transaction - ensures atomicity)
            const booking = await tx.booking.create({
                data: {
                    date: bookingStart,
                    endTime: bookingEnd,
                    status: "CONFIRMED",
                    notes: notes,
                    serviceId: service.id,
                    contactId: dbContact.id,
                    workspaceId: service.workspaceId
                }
            });

            return { booking, dbContact };
        }, {
            isolationLevel: 'Serializable', // Prevents phantom reads and race conditions
            maxWait: 5000, // Maximum time to wait for transaction slot
            timeout: 10000 // Maximum time for transaction to complete
        });

        const { booking, dbContact } = result;

        // 3. Trigger Automation (outside transaction - non-blocking)
        // We don't await to keep response fast
        triggerAutomation(service.workspaceId, "BOOKING_CREATED", { booking, contact: dbContact, service })
            .catch(err => console.error("[Automation] Failed to trigger:", err));

        // 4. Sync to Google Calendar (fire-and-forget, never blocks booking flow)
        syncBookingToCalendar(booking.id, service.workspaceId).catch((err) =>
            console.error("[Google Calendar] Background sync error:", err)
        );

        return NextResponse.json({ success: true, bookingId: booking.id });

    } catch (error: any) {
        console.error("Booking Creation Error:", error);

        // Handle specific transaction errors
        if (error.message?.startsWith("CONFLICT:")) {
            return NextResponse.json({ error: "Slot no longer available" }, { status: 409 });
        }

        if (error.message?.startsWith("INVENTORY:")) {
            return NextResponse.json({ 
                error: "Insufficient inventory",
                details: error.message.replace("INVENTORY:", "")
            }, { status: 409 });
        }

        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import {
  updateBookingCalendarEvent,
  cancelBookingCalendarEvent,
} from "@/lib/google-calendar";
import { triggerAutomation } from "@/lib/automation";
import { logInventoryChange } from "@/lib/inventory-log";

async function decrementInventoryForBooking(bookingId: string, workspaceId: string) {
  const booking = await prisma.booking.findUnique({
    where: { id: bookingId },
    include: {
      service: {
        include: {
          inventoryLinks: {
            include: { inventory: true },
          },
        },
      },
    },
  });

  if (!booking || booking.status === "COMPLETED") return;

  for (const link of booking.service.inventoryLinks) {
    const item = link.inventory;
    const previousQuantity = item.quantity;
    const newQuantity = Math.max(0, item.quantity - link.quantity);

    // Update inventory quantity
    await prisma.inventoryItem.update({
      where: { id: item.id },
      data: { quantity: newQuantity },
    });

    // Log the inventory change
    await logInventoryChange({
      itemId: item.id,
      previousQty: previousQuantity,
      newQty: newQuantity,
      reason: "booking_completed",
      referenceId: bookingId,
      referenceType: "booking",
      workspaceId,
    });

    if (newQuantity <= item.threshold) {
      await triggerAutomation(workspaceId, "INVENTORY_LOW", {
        item: {
          name: item.name,
          quantity: newQuantity,
          threshold: item.threshold,
          unit: item.unit,
          vendorEmail: item.vendorEmail,
        },
      });
    }
  }
}

export async function PUT(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const user = await getCurrentUser();
  if (!user || !user.workspaceId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { id } = await params;
  const data = await req.json();

  const booking = await prisma.booking.update({
    where: { id, workspaceId: user.workspaceId },
    data: {
      ...(data.status && { status: data.status }),
      ...(data.notes !== undefined && { notes: data.notes }),
      ...(data.date && { date: new Date(data.date) }),
      ...(data.serviceId && { serviceId: data.serviceId }),
    },
    include: { service: true, contact: true },
  });

  // Handle inventory decrement and calendar sync
  if (data.status === "COMPLETED") {
    decrementInventoryForBooking(id, user.workspaceId).catch((err) =>
      console.error("[Inventory] Decrement error:", err)
    );
  }

  // Sync calendar event updates (fire-and-forget)
  if (data.status === "CANCELLED" || data.status === "NO_SHOW") {
    cancelBookingCalendarEvent(id, user.workspaceId).catch((err) =>
      console.error("[Google Calendar] Cancel event error:", err)
    );
  } else if (data.date || data.serviceId) {
    updateBookingCalendarEvent(id, user.workspaceId).catch((err) =>
      console.error("[Google Calendar] Update event error:", err)
    );
  }

  return NextResponse.json({ booking });
}

export async function DELETE(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const user = await getCurrentUser();
  if (!user || !user.workspaceId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { id } = await params;
  await prisma.booking.update({
    where: { id, workspaceId: user.workspaceId },
    data: { status: "CANCELLED" },
  });

  // Cancel the Google Calendar event (fire-and-forget)
  cancelBookingCalendarEvent(id, user.workspaceId).catch((err) =>
    console.error("[Google Calendar] Cancel event error:", err)
  );

  return NextResponse.json({ success: true });
}

import { NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { triggerAutomation } from "@/lib/automation";
import { syncBookingToCalendar } from "@/lib/google-calendar";

export async function GET() {
  const user = await getCurrentUser();
  if (!user || !user.workspaceId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  if (user.role !== "OWNER" && !user.canAccessBookings)
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });

  console.log(`[API] Fetching bookings for workspace: ${user.workspaceId}`);
  const bookings = await prisma.booking.findMany({
    where: { workspaceId: user.workspaceId },
    include: {
      service: true,
      contact: true,
      _count: { select: { formSubmissions: true } },
    },
    orderBy: { date: "desc" },
  });

  console.log(`[API] Found ${bookings.length} bookings`);
  return NextResponse.json({ bookings });
}

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user || !user.workspaceId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  if (user.role !== "OWNER" && !user.canAccessBookings)
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });

  const { serviceId, contactId, date, notes } = await req.json();
  if (!serviceId || !contactId || !date)
    return NextResponse.json(
      { error: "Missing required fields" },
      { status: 400 }
    );

  const service = await prisma.service.findUnique({ where: { id: serviceId } });
  if (!service)
    return NextResponse.json({ error: "Service not found" }, { status: 404 });

  const contact = await prisma.contact.findUnique({ where: { id: contactId } });
  if (!contact)
    return NextResponse.json({ error: "Contact not found" }, { status: 404 });

  const startDate = new Date(date);
  const endTime = new Date(startDate.getTime() + service.duration * 60000);

  const booking = await prisma.booking.create({
    data: {
      date: startDate,
      endTime,
      serviceId,
      contactId,
      workspaceId: user.workspaceId,
      notes,
      status: "CONFIRMED",
    },
    include: { service: true, contact: true },
  });

  await triggerAutomation(user.workspaceId, "BOOKING_CREATED", {
    booking,
    contact,
    service,
  });

  // Sync to Google Calendar (fire-and-forget, never blocks booking flow)
  syncBookingToCalendar(booking.id, user.workspaceId).catch((err) =>
    console.error("[Google Calendar] Background sync error:", err)
  );

  return NextResponse.json({ booking }, { status: 201 });
}

