import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import {
  exchangeCalendarCode,
  getCalendarUserEmail,
} from "@/lib/google-calendar";

/**
 * GET /api/integrations/google-calendar/callback
 * Handles the Google OAuth callback after the user grants calendar access.
 */
export async function GET(req: Request) {
  const { searchParams } = new URL(req.url);
  const code = searchParams.get("code");
  const state = searchParams.get("state"); // workspaceId
  const error = searchParams.get("error");

  // Handle user denial
  if (error) {
    console.error("[Google Calendar] OAuth error:", error);
    return NextResponse.redirect(
      new URL("/settings?tab=integrations&calendar=denied", req.url)
    );
  }

  if (!code || !state) {
    return NextResponse.redirect(
      new URL("/settings?tab=integrations&calendar=error", req.url)
    );
  }

  try {
    // Verify the workspace exists
    const workspace = await prisma.workspace.findUnique({
      where: { id: state },
    });

    if (!workspace) {
      console.error("[Google Calendar] Invalid workspace in state:", state);
      return NextResponse.redirect(
        new URL("/settings?tab=integrations&calendar=error", req.url)
      );
    }

    // Exchange code for tokens
    const tokens = await exchangeCalendarCode(code);
    const tokenExpiry = new Date(Date.now() + tokens.expires_in * 1000);

    // Get the user's calendar email
    const calendarEmail = await getCalendarUserEmail(tokens.access_token);

    // Save tokens to workspace
    await prisma.workspace.update({
      where: { id: state },
      data: {
        googleCalendarConnected: true,
        googleCalendarAccessToken: tokens.access_token,
        googleCalendarRefreshToken:
          tokens.refresh_token || workspace.googleCalendarRefreshToken,
        googleCalendarTokenExpiry: tokenExpiry,
        googleCalendarEmail: calendarEmail,
        googleCalendarId: "primary",
      },
    });

    console.log(
      `[Google Calendar] Connected for workspace ${state} (${calendarEmail})`
    );

    return NextResponse.redirect(
      new URL("/settings?tab=integrations&calendar=success", req.url)
    );
  } catch (err) {
    console.error("[Google Calendar] Callback error:", err);
    return NextResponse.redirect(
      new URL("/settings?tab=integrations&calendar=error", req.url)
    );
  }
}

import { NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { listCalendarEvents } from "@/lib/google-calendar";

/**
 * GET /api/integrations/google-calendar/events
 * Fetches events from Google Calendar for the dashboard.
 */
export async function GET(req: Request) {
    const user = await getCurrentUser();
    if (!user?.workspaceId) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { searchParams } = new URL(req.url);
    const timeMinStr = searchParams.get("timeMin");
    const timeMaxStr = searchParams.get("timeMax");

    if (!timeMinStr || !timeMaxStr) {
        return NextResponse.json(
            { error: "Missing timeMin or timeMax query parameters" },
            { status: 400 }
        );
    }

    try {
        const events = await listCalendarEvents(
            user.workspaceId,
            new Date(timeMinStr),
            new Date(timeMaxStr)
        );

        // Map Google events to a format that can be handled by the UI
        const mappedEvents = events
            .filter((event) => {
                // Filter out events created by CareOps to avoid duplication
                // We identify them by looking for our eventId in the database, 
                // but for now we'll just filter out ones with our unique footer in description
                const description = event.description || "";
                return !description.includes("--- Managed by") && !description.includes("via CareOps ---");
            })
            .map((event) => ({
                id: `google-${event.id}`,
                summary: event.summary,
                description: event.description,
                location: event.location,
                start: event.start.dateTime || event.start.date,
                end: event.end.dateTime || event.end.date,
                isExternal: true,
            }));

        return NextResponse.json({ events: mappedEvents });
    } catch (error) {
        console.error("[API] Google Calendar events fetch error:", error);
        return NextResponse.json({ events: [] });
    }
}

