export async function PUT(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const user = await getCurrentUser();
  if (!user || !user.workspaceId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  if (user.role !== "OWNER" && !user.canAccessInventory)
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });

  const { id } = await params;
  const data = await req.json();

  const item = await prisma.inventoryItem.update({
    where: { id, workspaceId: user.workspaceId },
    data: {
      ...(data.name && { name: data.name }),
      ...(data.description !== undefined && { description: data.description }),
      ...(data.quantity !== undefined && { quantity: data.quantity }),
      ...(data.threshold !== undefined && { threshold: data.threshold }),
      ...(data.unit && { unit: data.unit }),
      ...(data.vendorName !== undefined && { vendorName: data.vendorName }),
      ...(data.vendorEmail !== undefined && { vendorEmail: data.vendorEmail }),
      ...(data.vendorPhone !== undefined && { vendorPhone: data.vendorPhone }),
    },
  });

  if (item.quantity <= item.threshold) {
    await triggerAutomation(user.workspaceId, "INVENTORY_LOW", { item });
  }

  return NextResponse.json({ item });
}

