        { error: 'Only workspace owners can configure voice settings' },
        { status: 403 }
      );
    }

    const body = await req.json();
    const { voiceAgentId, phoneNumberId, action } = body;

    if (action === 'test') {
      const vapiHealth = await checkVapiHealth();
      return NextResponse.json({
