        message: vapiHealth.healthy 
          ? 'VAPI connection successful' 
          : `VAPI connection failed: ${vapiHealth.error}`,
        health: vapiHealth,
      });
    }

    if (action === 'activate_voice' || action === 'deactivate_voice') {
