      return NextResponse.json({
        success: true,
        message: isActive 
          ? 'Voice agent activated' 
          : 'Voice agent deactivated',
      });
    }

    return NextResponse.json(
      { error: 'Invalid action' },
      { status: 400 }
    );
  } catch (error) {
    console.error('[Voice:Settings:POST] Error:', error);
    return NextResponse.json(
      { error: 'Failed to update voice settings' },
      { status: 500 }
    );
  }
}

