  const user = await getCurrentUser();
  if (!user || !user.workspaceId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const staff = await prisma.user.findMany({
    where: { workspaceId: user.workspaceId },
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
      canAccessInbox: true,
      canAccessBookings: true,
      canAccessForms: true,
      canAccessInventory: true,
      createdAt: true,
    },
    orderBy: { createdAt: "asc" },
  });

  return NextResponse.json({ staff });
}

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user || !user.workspaceId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  if (user.role !== "OWNER")
    return NextResponse.json(
      { error: "Only owners can add staff" },
      { status: 403 }
    );

  const {
    email,
    name,
    password,
    canAccessInbox,
    canAccessBookings,
    canAccessForms,
    canAccessInventory,
  } = await req.json();
  if (!email || !name || !password)
    return NextResponse.json(
      { error: "Email, name, and password are required" },
      { status: 400 }
    );

  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing)
    return NextResponse.json(
      { error: "Email already in use" },
      { status: 409 }
    );

  const passwordHash = await hashPassword(password);
  const staffUser = await prisma.user.create({
    data: {
      email,
      name,
      passwordHash,
      role: "STAFF",
      workspaceId: user.workspaceId,
      canAccessInbox: canAccessInbox ?? true,
      canAccessBookings: canAccessBookings ?? true,
      canAccessForms: canAccessForms ?? true,
      canAccessInventory: canAccessInventory ?? true,
    },
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
      canAccessInbox: true,
      canAccessBookings: true,
      canAccessForms: true,
      canAccessInventory: true,
    },
  });

  return NextResponse.json({ staff: staffUser }, { status: 201 });
}

export async function PUT(req: Request) {
  const user = await getCurrentUser();
  if (!user || !user.workspaceId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  if (user.role !== "OWNER")
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });

  const { id, name, email, password, canAccessInbox, canAccessBookings, canAccessForms, canAccessInventory } = await req.json();
  if (!id) return NextResponse.json({ error: "User ID is required" }, { status: 400 });

  const existingUser = await prisma.user.findUnique({
    where: { id },
  });

  if (!existingUser || existingUser.workspaceId !== user.workspaceId) {
    return NextResponse.json({ error: "User not found" }, { status: 404 });
  }

  const updateData: any = {
    name,
    email,
    canAccessInbox,
    canAccessBookings,
    canAccessForms,
    canAccessInventory,
  };

  if (password) {
    updateData.passwordHash = await hashPassword(password);
  }

  const staff = await prisma.user.update({
    where: { id },
    data: updateData,
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
      canAccessInbox: true,
      canAccessBookings: true,
      canAccessForms: true,
      canAccessInventory: true,
    },
  });

  return NextResponse.json({ staff });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { createToken, hashPassword } from "@/lib/auth";

export async function POST(req: Request) {
    if (process.env.NODE_ENV === "production") {
        return NextResponse.json({ error: "Not allowed in production" }, { status: 403 });
    }

    try {
        const { email, name, password, status, onboardingStep } = await req.json();

        // Cleanup existing user if any
        await prisma.user.deleteMany({ where: { email } });

        const workspace = await prisma.workspace.create({
            data: {
                name: `${name}'s Workspace`,
                status: status || "ONBOARDING",
                onboardingStep: onboardingStep || 1
            }
        });

        const passwordHash = await hashPassword(password || "password123");

        const user = await prisma.user.create({
            data: {
                email,
                name,
                passwordHash,
                role: "OWNER",
                workspaceId: workspace.id,
                emailVerified: new Date()
            }
        });

        const token = await createToken(user.id, workspace.id, user.role);

        return NextResponse.json({ token, user, workspace });
    } catch (error) {
        console.error("Seed error:", error);
        return NextResponse.json({ error: "Seed failed", details: String(error) }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { writeFile, mkdir } from "fs/promises";
import path from "path";
import { getCurrentUser } from "@/lib/auth";

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user || user.role !== "OWNER") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
  }

  const formData = await req.formData();
  const file = formData.get("file") as File;

  if (!file) {
    return NextResponse.json({ error: "No file received" }, { status: 400 });
  }

  const buffer = Buffer.from(await file.arrayBuffer());
  const filename = Date.now() + "-" + file.name.replace(/\s/g, "-");

  try {
    const uploadDir = path.join(process.cwd(), "public/uploads");
    await mkdir(uploadDir, { recursive: true });
    await writeFile(path.join(uploadDir, filename), buffer);

    return NextResponse.json({ 
      url: `/uploads/${filename}`,
      name: file.name 
    });
  } catch (error) {
    console.error("Upload error:", error);
    return NextResponse.json({ error: "Upload failed" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentUser, hashPassword, verifyPassword } from "@/lib/auth";

export async function PUT(req: Request) {
    try {
        const currentUser = await getCurrentUser();
        if (!currentUser) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { currentPassword, newPassword } = await req.json();

        if (!currentPassword || !newPassword) {
            return NextResponse.json(
                { error: "Current and new password are required" },
                { status: 400 }
            );
        }

        // Verify current password
        // We need to fetch the passwordHash which isn't in currentUser object usually (depends on auth implementation)
        // Let's fetch sensitive data explicitly
        const userWithPassword = await prisma.user.findUnique({
            where: { id: currentUser.id },
        });

        if (!userWithPassword || !userWithPassword.passwordHash) {
            // Should not happen for password-auth users, but safeguard
            return NextResponse.json({ error: "User not found" }, { status: 404 });
        }

        const isValid = await verifyPassword(currentPassword, userWithPassword.passwordHash);
        if (!isValid) {
            return NextResponse.json(
                { error: "Incorrect current password" },
                { status: 400 }
            );
        }

        // Hash new password and update
        const hashedPassword = await hashPassword(newPassword);
        await prisma.user.update({
            where: { id: currentUser.id },
            data: { passwordHash: hashedPassword },
        });

        return NextResponse.json({ message: "Password updated successfully" });
    } catch (error) {
        console.error("Change password error:", error);
        return NextResponse.json(
            { error: "Failed to update password" },
            { status: 500 }
        );
    }
}

