    }

    const { searchParams } = new URL(req.url);
    const activeOnly = searchParams.get('active') === 'true';

    const where: Record<string, unknown> = {
      workspaceId: user.workspaceId,
    };

    if (activeOnly) {
      where.isActive = true;
    }

