  } catch (error) {
    console.error('[VoiceAgent:POST] Error:', error);
    return NextResponse.json(
      { error: 'Failed to create voice agent' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getCurrentUser } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { endCall, getCallDetails, isVapiConfigured } from '@/lib/vapi';

interface RouteParams {
  params: Promise<{ id: string }>;
}

export async function GET(req: NextRequest, { params }: RouteParams) {
  try {
    const user = await getCurrentUser();
    if (!user?.workspaceId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id } = await params;

    const call = await prisma.voiceCall.findFirst({
      where: {
        id,
        workspaceId: user.workspaceId,
      },
      include: {
        contact: true,
      },
    });

    if (!call) {
      return NextResponse.json({ error: 'Call not found' }, { status: 404 });
    }

    let vapiDetails = null;
    if (call.callSid && isVapiConfigured()) {
      vapiDetails = await getCallDetails(call.callSid);
    }

    return NextResponse.json({
      ...call,
      vapiDetails,
    });
  } catch (error) {
    console.error('[Voice:Call:GET:Id] Error:', error);
    return NextResponse.json(
      { error: 'Failed to fetch call' },
      { status: 500 }
    );
  }
}

export async function POST(req: NextRequest, { params }: RouteParams) {
  try {
    const user = await getCurrentUser();
    if (!user?.workspaceId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id } = await params;
    const body = await req.json();
    const { action } = body;

    const call = await prisma.voiceCall.findFirst({
      where: {
        id,
        workspaceId: user.workspaceId,
      },
    });

    if (!call) {
      return NextResponse.json({ error: 'Call not found' }, { status: 404 });
    }

    if (action === 'end' && call.callSid) {
      if (!isVapiConfigured()) {
        return NextResponse.json(
          { error: 'VAPI not configured' },
          { status: 503 }
        );
      }

      const result = await endCall(call.callSid);

      if (!result.success) {
        return NextResponse.json(
          { error: result.error || 'Failed to end call' },
          { status: 500 }
        );
      }

      await prisma.voiceCall.update({
        where: { id },
        data: {
          status: 'COMPLETED',
          endedAt: new Date(),
        },
      });

      return NextResponse.json({ success: true });
    }

    if (action === 'update-summary') {
      const { summary, outcome } = body;

      const updated = await prisma.voiceCall.update({
        where: { id },
        data: {
          ...(summary && { summary }),
          ...(outcome && { outcome }),
        },
      });

      return NextResponse.json(updated);
    }

    return NextResponse.json(
      { error: 'Invalid action' },
      { status: 400 }
    );
  } catch (error) {
    console.error('[Voice:Call:POST] Error:', error);
    return NextResponse.json(
      { error: 'Failed to process call action' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getCurrentUser } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { initiateOutboundCall, isVapiConfigured } from '@/lib/vapi';

export async function POST(req: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user?.workspaceId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    if (!isVapiConfigured()) {
      return NextResponse.json(
        { error: 'VAPI not configured. Please add VAPI_API_KEY to environment.' },
        { status: 503 }
      );
    }

    const body = await req.json();
    const { phoneNumber, contactId, agentId, purpose, notes } = body;

    if (!phoneNumber) {
      return NextResponse.json(
        { error: 'Phone number is required' },
        { status: 400 }
      );
    }

    const workspaceId = user.workspaceId;
    let contact = null;

    if (contactId) {
      contact = await prisma.contact.findFirst({
        where: {
          id: contactId,
          workspaceId,
        },
      });
    } else if (phoneNumber) {
      contact = await prisma.contact.findFirst({
        where: {
          phone: phoneNumber,
          workspaceId,
        },
      });
    }

    let assistantId: string | undefined;
    if (agentId) {
      const agent = await prisma.voiceAgent.findFirst({
        where: {
          id: agentId,
          workspaceId,
          isActive: true,
        },
      });
      assistantId = agent?.vapiAssistantId || undefined;
    }

    const result = await initiateOutboundCall({
      phoneNumber,
      workspaceId,
      contactId: contact?.id,
      contactName: contact?.name,
      assistantId,
      metadata: {
        purpose,
        notes,
        initiatedBy: user.email,
      },
    });

    if (!result.success) {
      return NextResponse.json(
        { error: result.error || 'Failed to initiate call' },
        { status: 500 }
      );
    }

    const voiceCall = await prisma.voiceCall.create({
      data: {
        callSid: result.callId,
        direction: 'OUTBOUND',
        status: 'INITIATED',
        contactId: contact?.id,
        workspaceId,
        assistantId,
        metadata: JSON.stringify({ purpose, notes }),
      },
    });

    return NextResponse.json({
      success: true,
      callId: result.callId,
      voiceCall,
    });
  } catch (error) {
    console.error('[Voice:Call:POST] Error:', error);
    return NextResponse.json(
      { error: 'Failed to initiate call' },
      { status: 500 }
    );
  }
}

export async function GET(req: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user?.workspaceId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(req.url);
    const contactId = searchParams.get('contactId');
    const status = searchParams.get('status');
    const limit = parseInt(searchParams.get('limit') || '50');
    const offset = parseInt(searchParams.get('offset') || '0');

    const where: Record<string, unknown> = {
      workspaceId: user.workspaceId,
    };

    if (contactId) {
      where.contactId = contactId;
    }

    if (status) {
      where.status = status;
    }

    const [calls, total] = await Promise.all([
      prisma.voiceCall.findMany({
        where,
        include: {
          contact: true,
        },
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: offset,
      }),
      prisma.voiceCall.count({ where }),
    ]);

    return NextResponse.json({
      calls,
      pagination: {
        total,
        limit,
        offset,
        hasMore: offset + calls.length < total,
      },
    });
  } catch (error) {
    console.error('[Voice:Call:GET] Error:', error);
    return NextResponse.json(
      { error: 'Failed to fetch calls' },
      { status: 500 }
    );
  }
}

