        setEditingIndex({ type: null, index: -1 });
      } else {
        setIntakeForms(prev => [...prev, { ...newIntakeForm, documents: JSON.stringify(newIntakeForm.documents) }]);
      }
      setNewIntakeForm({ name: "", description: "", serviceId: "", documents: [] });
