                  <p className="text-xs text-gray-500 truncate">{booking.service}</p>
                </div>
                <Badge
                  variant="outline"
                  className={cn("text-[10px] font-semibold shrink-0", statusColors[booking.status] || statusColors.PENDING)}
                >
                  {booking.status.replace("_", " ")}
                </Badge>
              </button>
            ))}
            {bookings.length > 6 && (
              <p className="text-xs text-center text-gray-400 pt-1">
                +{bookings.length - 6} more bookings
              </p>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { CheckCircle, Copy, ExternalLink, ToggleLeft, ToggleRight, Trash2, FileText } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ContactFormDTO, IntakeFormDTO } from "@/types/dto";

interface FormListProps {
  forms: (ContactFormDTO | IntakeFormDTO)[];
  type: "contact" | "intake";
  onToggle: (id: string, isActive: boolean) => void;
  onDelete: (id: string) => void;
  copied: string;
  onCopy: (slug: string, type: string) => void;
  deleting: string;
}

export function FormList({
  forms,
  type,
  onToggle,
  onDelete,
  copied,
  onCopy,
  deleting,
}: FormListProps) {
  if (forms.length === 0) {
    return (
      <div className="text-center py-12">
        <FileText className="w-12 h-12 text-gray-300 mx-auto mb-3" />
        <p className="text-gray-500 mb-1">No {type} forms yet</p>
        <p className="text-xs text-gray-400 mb-4">
          Create a {type} form to start collecting data.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {forms.map((form) => (
        <Card key={form.id}>
          <CardContent className="flex items-center justify-between py-4">
            <div>
              <p className="font-medium">{form.name}</p>
              {type === "contact" ? (
                <p className="text-xs text-gray-500 mt-1">Slug: {form.slug}</p>
              ) : (
                <div className="flex items-center gap-2 mt-1">
                  {(form as IntakeFormDTO).service && (
                    <Badge variant="secondary">
                      {(form as IntakeFormDTO).service?.name}
                    </Badge>
                  )}
                  <span className="text-xs text-gray-500">
                    {(form as IntakeFormDTO)._count?.submissions || 0} submissions
                  </span>
                </div>
              )}
            </div>
            <div className="flex items-center gap-2">
              <Badge variant={form.isActive ? "default" : "secondary"}>
                {form.isActive ? "Active" : "Inactive"}
              </Badge>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onToggle(form.id, form.isActive)}
                title={form.isActive ? "Deactivate form" : "Activate form"}
              >
                {form.isActive ? (
                  <ToggleRight className="w-4 h-4 text-green-600" />
                ) : (
                  <ToggleLeft className="w-4 h-4 text-gray-400" />
                )}
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => onCopy(form.slug, type === "contact" ? "contact" : "form")}
              >
                {copied === form.slug ? (
                  <CheckCircle className="w-3 h-3 mr-1" />
                ) : (
                  <Copy className="w-3 h-3 mr-1" />
                )}
                {copied === form.slug ? "Copied!" : "Copy Link"}
              </Button>
              <Button
                variant="ghost"
                size="sm"
                onClick={() =>
                  window.open(
                    `/${type === "contact" ? "contact" : "form"}/${form.slug}`,
                    "_blank"
                  )
                }
              >
                <ExternalLink className="w-3 h-3" />
              </Button>
              <Button
                variant="ghost"
                size="sm"
                className="text-red-500 hover:text-red-700 hover:bg-red-50"
                disabled={deleting === form.id}
                onClick={() => {
                  if (confirm("Are you sure you want to delete this form?"))
                    onDelete(form.id);
                }}
              >
                <Trash2 className="w-3 h-3" />
              </Button>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

"use client";

import { AlertTriangle, CheckCircle, Send } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { FormSubmissionDTO } from "@/types/dto";

interface SubmissionDetailDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  submission: FormSubmissionDTO | null;
  onUpdateStatus: (id: string, status: string) => void;
  onResend: (id: string) => void;
}

export function SubmissionDetailDialog({
  open,
  onOpenChange,
  submission,
  onUpdateStatus,
  onResend,
}: SubmissionDetailDialogProps) {
  if (!submission) return null;

  const statusBadge = (status: string) => {
    switch (status) {
      case "PENDING":
        return <Badge variant="secondary">Pending</Badge>;
      case "SENT":
        return <Badge variant="secondary">Sent</Badge>;
      case "COMPLETED":
        return <Badge variant="default" className="bg-green-600">Completed</Badge>;
      case "OVERDUE":
        return <Badge variant="destructive">Overdue</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Submission Details</DialogTitle>
          <DialogDescription>
            View submission information and manage its status.
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-5">
          <div className="flex items-center justify-between">
            {statusBadge(submission.status)}
            <p className="text-xs text-gray-400">
              Submitted {new Date(submission.createdAt).toLocaleString()}
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-xs text-gray-500 mb-1">Contact</p>
              <p className="font-medium text-sm">
                {submission.contact?.name || "Unknown"}
              </p>
              {submission.contact?.email && (
                <p className="text-xs text-gray-500 mt-0.5">
                  {submission.contact.email}
                </p>
              )}
              {submission.contact?.phone && (
                <p className="text-xs text-gray-500">
                  {submission.contact.phone}
                </p>
              )}
            </div>
            <div>
              <p className="text-xs text-gray-500 mb-1">Form</p>
              <p className="font-medium text-sm">
                {submission.intakeForm?.name || "Contact Form"}
              </p>
            </div>
          </div>

          {submission.data && Object.keys(submission.data).length > 0 && (
            <div>
              <p className="text-xs text-gray-500 mb-2">Submission Data</p>
              <div className="bg-gray-50 rounded-md p-3 space-y-2 max-h-60 overflow-y-auto">
                {Object.entries(submission.data).map(([key, value]) => (
                  <div key={key}>
                    <p className="text-xs font-medium text-gray-600 capitalize">
                      {key.replace(/([A-Z])/g, " $1").replace(/_/g, " ")}
                    </p>
                    <p className="text-sm">{String(value)}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="flex gap-2 pt-2 border-t">
            {(submission.status === "PENDING" ||
              submission.status === "SENT") && (
              <Button
                size="sm"
                variant="outline"
                className="text-blue-600"
                onClick={() => onResend(submission.id)}
              >
                <Send className="w-3 h-3 mr-1" /> Re-send Form
              </Button>
            )}
            {submission.status !== "COMPLETED" && (
              <Button
                size="sm"
                className="bg-green-600 hover:bg-green-700 text-white"
                onClick={() => {
                  onUpdateStatus(submission.id, "COMPLETED");
                  onOpenChange(false);
                }}
              >
                <CheckCircle className="w-3 h-3 mr-1" /> Mark Completed
              </Button>
            )}
            {submission.status !== "OVERDUE" &&
              submission.status !== "COMPLETED" && (
                <Button
                  size="sm"
                  variant="outline"
                  className="text-red-600"
                  onClick={() => {
                    onUpdateStatus(submission.id, "OVERDUE");
                    onOpenChange(false);
                  }}
                >
                  <AlertTriangle className="w-3 h-3 mr-1" /> Mark Overdue
                </Button>
              )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

