"use client";

import { useState } from "react";
import { Send, Loader2, Mail, Smartphone, MessageCircle, ChevronDown } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

type SendChannel = "email" | "sms";

interface ChatInputProps {
  inputText: string;
  setInputText: (text: string) => void;
  onSend: (channel?: SendChannel) => void;
  sending: boolean;
  disabled?: boolean;
  contactHasPhone?: boolean;
  contactHasEmail?: boolean;
}

const channelConfig: Record<SendChannel, { icon: typeof Mail; label: string; color: string }> = {
  email: { icon: Mail, label: "Email", color: "text-blue-600" },
  sms: { icon: Smartphone, label: "SMS", color: "text-blue-600" },
};

export function ChatInput({
  inputText,
  setInputText,
  onSend,
  sending,
  disabled,
  contactHasPhone,
  contactHasEmail,
}: ChatInputProps) {
  const [channel, setChannel] = useState<SendChannel>("email");
  const [showChannelPicker, setShowChannelPicker] = useState(false);

  const config = channelConfig[channel];
  const ChannelIcon = config.icon;

  const availableChannels = [
    ...(contactHasEmail !== false ? [{ key: "email" as SendChannel }] : []),
    ...(contactHasPhone ? [{ key: "sms" as SendChannel }] : []),
  ];

  const handleSend = () => {
    onSend(channel);
    setShowChannelPicker(false);
  };

  return (
    <div className="p-3 sm:p-4 bg-white border-t border-gray-200">
      {/* Channel selector dropdown */}
      {showChannelPicker && (
        <div className="mb-2 flex gap-1 p-1 bg-gray-50 rounded-lg border border-gray-200">
          {availableChannels.map(({ key }) => {
            const cfg = channelConfig[key];
            const Icon = cfg.icon;
            const isActive = channel === key;
            return (
              <button
                key={key}
                onClick={() => {
                  setChannel(key);
                  setShowChannelPicker(false);
                }}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded text-xs font-medium transition-all ${isActive
                    ? "bg-white shadow-sm border border-gray-200"
                    : "hover:bg-gray-100 text-gray-500"
                  }`}
              >
                <Icon className={`w-3.5 h-3.5 ${isActive ? cfg.color : ""}`} />
                {cfg.label}
              </button>
            );
          })}
        </div>
      )}

      <div className="flex items-end gap-2 bg-white rounded-xl border border-gray-300 p-2 focus-within:ring-2 focus-within:ring-blue-100 focus-within:border-blue-400 transition-all">
        {/* Channel indicator button */}
        {availableChannels.length > 1 && (
          <button
            onClick={() => setShowChannelPicker(!showChannelPicker)}
            className="flex items-center gap-0.5 px-2 py-1.5 rounded-md hover:bg-gray-100 transition-colors mb-1 shrink-0"
            title={`Sending via ${config.label}`}
          >
            <ChannelIcon className={`w-4 h-4 ${config.color}`} />
            <ChevronDown className="w-3 h-3 text-gray-400" />
          </button>
        )}

        <Textarea
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          placeholder={`Type a message (via ${config.label})...`}
          className="min-h-[40px] max-h-[140px] border-none focus-visible:ring-0 px-2 py-2 resize-none shadow-none"
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              handleSend();
            }
          }}
          disabled={disabled}
        />
        <Button
          size="icon"
          className="h-8 w-8 mb-1 shrink-0 bg-blue-600 hover:bg-blue-700"
          onClick={handleSend}
          disabled={!inputText.trim() || sending || disabled}
        >
          {sending ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <Send className="w-4 h-4" />
          )}
        </Button>
      </div>
    </div>
  );
}

"use client";

import { format } from "date-fns";
import { Search, X, Inbox as InboxIcon, MessageSquare } from "lucide-react";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { ConversationDTO } from "@/types/dto";

interface ConversationListProps {
  conversations: ConversationDTO[];
  activeId: string | null;
  onSelect: (id: string) => void;
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  totalUnread: number;
}

export function ConversationList({
  conversations,
  activeId,
  onSelect,
  searchQuery,
  setSearchQuery,
  totalUnread,
}: ConversationListProps) {
  const filteredConversations = conversations.filter(
    (c) =>
      c.contactName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      c.lastMessage?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="flex flex-col h-full bg-white border-r border-gray-200">
      <div className="p-4 border-b border-gray-200 flex items-center justify-between bg-gray-50/50">
        <h1 className="font-semibold text-lg flex items-center gap-2">
          <MessageSquare className="w-5 h-5 text-blue-600" /> Inbox
          {totalUnread > 0 && (
            <Badge
              variant="destructive"
              className="ml-1 rounded-full px-1.5 py-0.5 text-[10px] leading-none"
            >
              {totalUnread}
            </Badge>
          )}
        </h1>
      </div>
      <div className="p-2">
        <div className="relative">
          <Search className="absolute left-3 top-2.5 h-4 w-4 text-gray-400" />
          <Input
            placeholder="Search messages..."
            className="pl-9 bg-gray-50 border-none focus-visible:ring-1"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          {searchQuery && (
            <button
              onClick={() => setSearchQuery("")}
              className="absolute right-3 top-2.5"
            >
              <X className="h-4 w-4 text-gray-400 hover:text-gray-600" />
            </button>
          )}
        </div>
      </div>
      <ScrollArea className="flex-1">
        <div className="space-y-1 p-2">
          {filteredConversations.map((c) => (
            <button
              key={c.id}
              onClick={() => onSelect(c.id)}
              className={cn(
                "w-full text-left p-3 rounded-lg flex items-start gap-3 transition-colors",
                activeId === c.id ? "bg-blue-50" : "hover:bg-gray-100"
              )}
            >
              <div className="relative">
                <Avatar className="w-10 h-10 border border-gray-200">
                  <AvatarFallback className="bg-white text-blue-600">
                    {c.contactName.charAt(0).toUpperCase()}
                  </AvatarFallback>
                </Avatar>
                {c.unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-blue-600 text-[9px] font-bold text-white">
                    {c.unreadCount > 9 ? "9+" : c.unreadCount}
                  </span>
                )}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-baseline mb-1">
                  <span
                    className={cn(
                      "font-medium truncate",
                      c.unreadCount > 0 ? "text-gray-900" : "text-gray-700"
                    )}
                  >
                    {c.contactName}
                  </span>
                  <span className="text-xs text-gray-400 whitespace-nowrap ml-2">
                    {format(new Date(c.lastMessageAt), "MMM d")}
                  </span>
                </div>
                <p
                  className={cn(
                    "text-xs truncate",
                    c.unreadCount > 0
                      ? "font-medium text-gray-900"
                      : "text-gray-500"
                  )}
                >
                  {c.lastMessage}
                </p>
              </div>
            </button>
          ))}
          {filteredConversations.length === 0 && conversations.length > 0 && (
            <div className="text-center p-8 text-gray-400 text-sm">
              No conversations match &quot;{searchQuery}&quot;
            </div>
          )}
          {conversations.length === 0 && (
            <div className="flex flex-col items-center justify-center p-10 text-gray-400">
              <InboxIcon className="w-12 h-12 mb-3 opacity-30" />
              <p className="font-medium text-gray-500 mb-1">Inbox is empty</p>
              <p className="text-xs text-center">
                Conversations will appear here when contacts send messages or you
                start new ones.
              </p>
            </div>
          )}
        </div>
      </ScrollArea>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { format } from "date-fns";
import { Mail, SmartphoneIcon, Loader2 } from "lucide-react";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { cn } from "@/lib/utils";
import { MessageDTO } from "@/types/dto";

interface MessageThreadProps {
  messages: MessageDTO[];
  loading: boolean;
  contactName: string;
}

export function MessageThread({ messages, loading, contactName }: MessageThreadProps) {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  if (loading) {
    return (
      <div className="flex justify-center p-4">
        <Loader2 className="animate-spin text-gray-400" />
      </div>
    );
  }

  return (
    <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-4" ref={scrollRef}>
      {messages.map((msg, i) => {
        const showAvatar = i === 0 || messages[i - 1].direction !== msg.direction;
        const channel = msg.channel || "EMAIL";
        return (
          <div
            key={msg.id}
            className={cn(
              "flex w-full mb-2",
              msg.direction === "OUTBOUND" ? "justify-end" : "justify-start"
            )}
          >
            <div
              className={cn(
                "flex items-end max-w-[85%] sm:max-w-[70%] gap-2",
                msg.direction === "OUTBOUND" ? "flex-row-reverse" : "flex-row"
              )}
            >
              {msg.direction === "INBOUND" && showAvatar && (
                <Avatar className="w-6 h-6 mb-1">
                  <AvatarFallback className="text-[10px] bg-blue-100 text-blue-700">
                    {contactName.charAt(0).toUpperCase()}
                  </AvatarFallback>
                </Avatar>
              )}
              {!showAvatar && msg.direction === "INBOUND" && <div className="w-6" />}

              <div
                className={cn(
                  "p-3 rounded-2xl text-sm leading-relaxed shadow-sm",
                  msg.direction === "OUTBOUND"
                    ? "bg-blue-600 text-white rounded-br-none"
                    : "bg-white border border-gray-200 text-gray-800 rounded-bl-none"
                )}
              >
                <div className="whitespace-pre-wrap break-words">{msg.content}</div>
                <div
                  className={cn(
                    "flex items-center gap-1.5 mt-1 text-right",
                    msg.direction === "OUTBOUND" ? "text-blue-100" : "text-gray-400"
                  )}
                >
                  <span
                    className={cn(
                      "inline-flex items-center gap-0.5 text-[9px] font-medium rounded px-1 py-0.5",
                      msg.direction === "OUTBOUND"
                        ? "bg-blue-500/30 text-blue-100"
                        : "bg-gray-100 text-gray-500"
                    )}
                  >
                    {channel === "SMS" ? (
                      <SmartphoneIcon className="w-2.5 h-2.5" />
                    ) : (
                      <Mail className="w-2.5 h-2.5" />
                    )}
                    {channel}
                  </span>
                  <span className="text-[10px] opacity-70">
                    {format(new Date(msg.createdAt), "h:mm a")}
                    {msg.status === "FAILED" && " • Failed"}
                  </span>
                </div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { InventoryItemDTO } from "@/types/dto";

interface InventoryDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  item: InventoryItemDTO | null; // null for create, object for edit
  onSave: (data: Partial<InventoryItemDTO>) => Promise<void>;
}

export function InventoryDialog({
  open,
  onOpenChange,
  item,
  onSave,
}: InventoryDialogProps) {
  const [form, setForm] = useState({
    name: "",
    description: "",
    quantity: "0",
    threshold: "5",
    unit: "units",
    vendorName: "",
    vendorEmail: "",
    vendorPhone: "",
  });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (item) {
      setForm({
        name: item.name,
        description: item.description || "",
        quantity: String(item.quantity),
        threshold: String(item.threshold),
        unit: item.unit || "units",
        vendorName: item.vendorName || "",
        vendorEmail: item.vendorEmail || "",
        vendorPhone: item.vendorPhone || "",
      });
    } else {
      setForm({
        name: "",
        description: "",
        quantity: "0",
        threshold: "5",
        unit: "units",
        vendorName: "",
        vendorEmail: "",
        vendorPhone: "",
      });
    }
  }, [item, open]);

  const handleSave = async () => {
    if (!form.name) return;
    setSaving(true);
    try {
      await onSave({
        ...form,
        quantity: parseInt(form.quantity),
        threshold: parseInt(form.threshold),
      });
      onOpenChange(false);
    } catch (error) {
      console.error(error);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>
            {item ? "Edit Inventory Item" : "Add Inventory Item"}
          </DialogTitle>
          <DialogDescription>
            {item
              ? "Update item details below."
              : "Track new resources used in your business."}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2 col-span-2">
              <Label>Item Name *</Label>
              <Input
                placeholder="Surgical Gloves"
                value={form.name}
                onChange={(e) =>
                  setForm((p) => ({ ...p, name: e.target.value }))
                }
              />
            </div>
            <div className="space-y-2">
              <Label>Quantity</Label>
              <Input
                type="number"
                value={form.quantity}
                onChange={(e) =>
                  setForm((p) => ({ ...p, quantity: e.target.value }))
                }
              />
            </div>
            <div className="space-y-2">
              <Label>Low Stock Threshold</Label>
              <Input
                type="number"
                value={form.threshold}
                onChange={(e) =>
                  setForm((p) => ({ ...p, threshold: e.target.value }))
                }
              />
            </div>
            <div className="space-y-2">
              <Label>Unit</Label>
              <Input
                placeholder="boxes"
                value={form.unit}
                onChange={(e) =>
                  setForm((p) => ({ ...p, unit: e.target.value }))
                }
              />
            </div>
            <div className="space-y-2">
              <Label>Description</Label>
              <Input
                placeholder="Size L, latex-free"
                value={form.description}
                onChange={(e) =>
                  setForm((p) => ({ ...p, description: e.target.value }))
                }
              />
            </div>
          </div>
          <div className="border-t pt-4 space-y-3">
            <p className="text-sm font-medium text-gray-700">
              Vendor (optional)
            </p>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Vendor Name</Label>
                <Input
                  value={form.vendorName}
                  onChange={(e) =>
                    setForm((p) => ({ ...p, vendorName: e.target.value }))
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>Vendor Email</Label>
                <Input
                  type="email"
                  value={form.vendorEmail}
                  onChange={(e) =>
                    setForm((p) => ({ ...p, vendorEmail: e.target.value }))
                  }
                />
              </div>
              <div className="space-y-2 col-span-2">
                <Label>Vendor Phone</Label>
                <Input
                  value={form.vendorPhone}
                  onChange={(e) =>
                    setForm((p) => ({ ...p, vendorPhone: e.target.value }))
                  }
                />
              </div>
            </div>
          </div>
          <Button
            onClick={handleSave}
            className="w-full bg-blue-600 hover:bg-blue-700 font-bold"
            disabled={saving}
          >
            {saving ? "Saving..." : item ? "Save Changes" : "Create Item"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { Edit2, Mail, Package, Save, Sparkles, Trash2, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";
import { InventoryItemDTO } from "@/types/dto";

interface InventoryListProps {
  items: InventoryItemDTO[];
  forecast: Record<string, { daysRemaining: number | string; confidence: string }>;
  onUpdateQuantity: (id: string, qty: number) => void;
  onDelete: (id: string) => void;
  onEdit: (item: InventoryItemDTO) => void;
  onNotifyVendor: (item: InventoryItemDTO) => void;
  deletingId: string | null;
}

export function InventoryList({
  items,
  forecast,
  onUpdateQuantity,
  onDelete,
  onEdit,
  onNotifyVendor,
  deletingId,
}: InventoryListProps) {
  const [editId, setEditId] = useState<string | null>(null);
  const [editQty, setEditQty] = useState("");
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);

  if (items.length === 0) {
    return (
      <div className="text-center py-20 bg-white rounded-2xl border-2 border-dashed border-gray-100 italic transition-colors">
        <Package className="w-16 h-16 text-gray-200 mx-auto mb-4" />
        <h3 className="text-lg font-medium text-gray-400">
          Your inventory is empty
        </h3>
        <p className="text-sm text-gray-400 mt-1">
          Start tracking supplies to see AI forecasting in action.
        </p>
      </div>
    );
  }

  return (
    <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
      {items.map((item) => {
        const isLow = item.quantity <= item.threshold;
        const itemForecast = forecast[item.name];
        const pct =
          item.threshold > 0
            ? Math.min((item.quantity / (item.threshold * 3)) * 100, 100)
            : 100;

        return (
          <Card
            key={item.id}
            className={cn(
              "transition-all hover:shadow-md border-0 bg-white shadow-sm overflow-hidden",
              isLow && "ring-1 ring-red-100"
            )}
          >
            <CardContent className="p-0">
              <div className="p-6">
                <div className="flex items-start justify-between mb-4">
                  <div className="min-w-0 flex-1">
                    <p className="font-bold text-gray-900 truncate">
                      {item.name}
                    </p>
                    {item.description && (
                      <p className="text-xs text-gray-500 mt-1 truncate">
                        {item.description}
                      </p>
                    )}
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    {isLow && (
                      <Badge
                        variant="destructive"
                        className="animate-pulse shadow-sm text-[10px] font-bold px-1.5 h-5 uppercase tracking-tighter"
                      >
                        Critical
                      </Badge>
                    )}
                    {itemForecast && (
                      <div className="flex items-center gap-1 text-[10px] font-bold text-purple-600 bg-purple-50 px-2 py-0.5 rounded-full border border-purple-100">
                        <Sparkles className="w-2.5 h-2.5" />
                        {itemForecast.daysRemaining} days left
                      </div>
                    )}
                  </div>
                </div>

                <div className="mb-4">
                  {editId === item.id ? (
                    <div className="flex items-center gap-2">
                      <Input
                        type="number"
                        autoFocus
                        value={editQty}
                        onChange={(e) => setEditQty(e.target.value)}
                        className="h-10 w-24 text-lg font-bold"
                      />
                      <Button
                        size="icon"
                        className="bg-green-600 hover:bg-green-700 shrink-0"
                        onClick={() => {
                          onUpdateQuantity(item.id, parseInt(editQty));
                          setEditId(null);
                        }}
                      >
                        <Save className="w-4 h-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="icon"
                        className="shrink-0"
                        onClick={() => setEditId(null)}
                      >
                        <X className="w-4 h-4" />
                      </Button>
                    </div>
                  ) : (
                    <div
                      className="flex items-baseline gap-1 cursor-pointer group"
                      onClick={() => {
                        setEditId(item.id);
                        setEditQty(String(item.quantity));
                      }}
                    >
                      <span className="text-3xl font-black text-gray-900 tracking-tighter">
                        {item.quantity}
                      </span>
                      <span className="text-sm font-medium text-gray-500 uppercase">
                        {item.unit}
                      </span>
                      <Edit2 className="w-3.5 h-3.5 text-gray-300 opacity-0 group-hover:opacity-100 transition-opacity ml-1" />
                    </div>
                  )}
                </div>

                <div className="space-y-2">
                  <div className="flex justify-between text-[10px] uppercase font-bold tracking-widest text-gray-400">
                    <span>Stock Level</span>
                    <span>Threshold: {item.threshold}</span>
                  </div>
                  <Progress
                    value={pct}
                    className={cn(
                      "h-2 bg-gray-100",
                      isLow && "[&>div]:bg-red-500"
                    )}
                  />
                </div>
              </div>

              <div className="px-6 py-3 bg-gray-50/50 flex items-center justify-between border-t border-gray-50">
                <div className="flex items-baseline gap-2">
                  <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wider italic">
                    Vendor
                  </span>
                  <span className="text-xs font-semibold text-gray-600 truncate max-w-[120px]">
                    {item.vendorName || "Not assigned"}
                  </span>
                </div>
                <div className="flex items-center gap-1">
                  {isLow && item.vendorEmail && (
                    <Button
                      variant="outline"
                      size="sm"
                      className="text-orange-600 border-orange-200 hover:bg-orange-50 h-8 px-2 text-[10px] gap-1"
                      onClick={() => onNotifyVendor(item)}
                    >
                      <Mail className="w-3 h-3" /> Notify Vendor
                    </Button>
                  )}
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-gray-400 hover:text-blue-600 h-8 px-2"
                    onClick={() => onEdit(item)}
                  >
                    <Edit2 className="w-3.5 h-3.5" />
                  </Button>
                  <Dialog
                    open={deleteConfirmId === item.id}
                    onOpenChange={(open) =>
                      setDeleteConfirmId(open ? item.id : null)
                    }
                  >
                    <DialogTrigger asChild>
                      <Button
                        variant="ghost"
                        size="sm"
                        className="text-red-400 hover:text-red-600 h-8 px-2"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </Button>
                    </DialogTrigger>
                    <DialogContent>
                      <DialogHeader>
                        <DialogTitle>Delete Inventory Item</DialogTitle>
                        <DialogDescription>
                          Are you sure you want to delete{" "}
                          <span className="font-semibold">
                            &quot;{item.name}&quot;
                          </span>
                          ? This action cannot be undone.
                        </DialogDescription>
                      </DialogHeader>
                      <DialogFooter className="gap-2">
                        <Button
                          variant="outline"
                          onClick={() => setDeleteConfirmId(null)}
                        >
                          Cancel
                        </Button>
                        <Button
                          variant="destructive"
                          onClick={() => {
                            onDelete(item.id);
                            setDeleteConfirmId(null);
                          }}
                          disabled={deletingId === item.id}
                        >
                          {deletingId === item.id ? "Deleting..." : "Delete"}
                        </Button>
                      </DialogFooter>
                    </DialogContent>
                  </Dialog>
                </div>
              </div>
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";
import { Bell, Search, X, Clock, Calendar, Package, MessageSquare, FileText, Zap, ExternalLink, CheckCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import { useRouter } from "next/navigation";

interface HeaderProps {
  title: string;
  subtitle?: string;
  alertCount?: number;
  children?: React.ReactNode;
}

interface AlertItem {
  id: string;
  type: string;
  title: string;
  message: string;
  isRead: boolean;
  actionUrl: string | null;
  createdAt: string;
}

const alertTypeConfig: Record<string, { icon: React.ElementType; color: string }> = {
  booking: { icon: Calendar, color: "text-blue-600" },
  inventory: { icon: Package, color: "text-red-600" },
  communication: { icon: MessageSquare, color: "text-green-600" },
  form: { icon: FileText, color: "text-purple-600" },
  automation: { icon: Zap, color: "text-amber-600" },
};

function getRelativeTime(dateStr: string): string {
  const now = new Date();
  const date = new Date(dateStr);
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  if (diffMins < 1) return "Just now";
  if (diffMins < 60) return `${diffMins}m ago`;
  const diffHours = Math.floor(diffMins / 60);
  if (diffHours < 24) return `${diffHours}h ago`;
  const diffDays = Math.floor(diffHours / 24);
  if (diffDays < 7) return `${diffDays}d ago`;
  return date.toLocaleDateString();
}

export function Header({ title, subtitle, children }: HeaderProps) {
  const router = useRouter();
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<{ type: string; label: string; href: string }[]>([]);

  const [bellOpen, setBellOpen] = useState(false);
  const [alerts, setAlerts] = useState<AlertItem[]>([]);
  const [loadingAlerts, setLoadingAlerts] = useState(false);

  const bellRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLDivElement>(null);

  const unreadCount = alerts.filter((a) => !a.isRead).length;

  // Fetch alerts
  const fetchAlerts = useCallback(async () => {
    setLoadingAlerts(true);
    try {
      const res = await fetch("/api/alerts");
      if (res.ok) {
        const data = await res.json();
        setAlerts(data.alerts || []);
      }
    } catch {
      // silent
    } finally {
      setLoadingAlerts(false);
    }
  }, []);

  useEffect(() => {
    fetchAlerts();
    const interval = setInterval(fetchAlerts, 60000);
    return () => clearInterval(interval);
  }, [fetchAlerts]);

  // Mark all as read
  const markAllRead = async () => {
    const unreadIds = alerts.filter((a) => !a.isRead).map((a) => a.id);
    if (unreadIds.length === 0) return;
    try {
      await fetch("/api/alerts", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ids: unreadIds }),
      });
      setAlerts((prev) => prev.map((a) => ({ ...a, isRead: true })));
    } catch {
      // silent
    }
  };

  // Close dropdowns on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (bellRef.current && !bellRef.current.contains(e.target as Node)) {
        setBellOpen(false);
      }
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) {
        setSearchOpen(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  // Global search with quick navigation
  useEffect(() => {
    if (!searchQuery.trim()) {
      setSearchResults([]);
      return;
    }

    const q = searchQuery.toLowerCase();
    const pages = [
      { type: "page", label: "Dashboard", href: "/dashboard", keywords: ["dashboard", "home", "overview", "metrics"] },
      { type: "page", label: "Inbox", href: "/inbox", keywords: ["inbox", "messages", "conversations", "chat", "reply"] },
      { type: "page", label: "Bookings", href: "/bookings", keywords: ["bookings", "appointments", "schedule", "calendar"] },
      { type: "page", label: "Forms", href: "/forms", keywords: ["forms", "intake", "contact", "submissions"] },
      { type: "page", label: "Inventory", href: "/inventory", keywords: ["inventory", "stock", "supplies", "items"] },
      { type: "page", label: "Staff", href: "/staff", keywords: ["staff", "team", "members", "permissions"] },
      { type: "page", label: "Automation", href: "/automation", keywords: ["automation", "rules", "triggers", "workflows"] },
      { type: "page", label: "Settings", href: "/settings", keywords: ["settings", "workspace", "profile", "security", "export"] },
    ];

    const matches = pages.filter(
      (p) => p.label.toLowerCase().includes(q) || p.keywords.some((k) => k.includes(q))
    );

    // Also match alerts
    const alertMatches = alerts
      .filter((a) => a.title.toLowerCase().includes(q) || a.message.toLowerCase().includes(q))
      .slice(0, 3)
      .map((a) => ({
        type: "alert",
        label: `${a.title}: ${a.message}`,
        href: a.actionUrl || "/dashboard",
      }));

    setSearchResults([...matches, ...alertMatches].slice(0, 8));
  }, [searchQuery, alerts]);

  const navigateTo = (href: string) => {
    router.push(href);
    setSearchOpen(false);
    setSearchQuery("");
    setBellOpen(false);
  };

  return (
    <header className="sticky top-0 z-30 bg-white/80 backdrop-blur-sm border-b border-gray-200">
      <div className="flex items-center justify-between px-4 sm:px-6 py-3 sm:py-4">
        <div className="flex-1 min-w-0 mr-4">
          <h1 className="text-xl sm:text-2xl font-bold text-gray-900 truncate">{title}</h1>
          {subtitle && <p className="text-xs sm:text-sm text-gray-500 mt-0.5 truncate">{subtitle}</p>}
        </div>
        <div className="flex items-center gap-3">
          {children}

          {/* Global Search - Desktop & Mobile Toggle */}
          <div className="relative" ref={searchRef}>
            <div className="hidden md:block">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <Input
                className="pl-9 w-64 bg-gray-50 h-9"
                placeholder="Search..."
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  setSearchOpen(true);
                }}
                onFocus={() => setSearchOpen(true)}
              />
              {searchQuery && (
                <button
                  onClick={() => { setSearchQuery(""); setSearchResults([]); }}
                  className="absolute right-3 top-1/2 -translate-y-1/2"
                >
                  <X className="w-3 h-3 text-gray-400 hover:text-gray-600" />
                </button>
              )}
            </div>

            <Button
              variant="ghost"
              size="icon"
              className="md:hidden"
              onClick={() => setSearchOpen(!searchOpen)}
            >
              <Search className="w-5 h-5 text-gray-500" />
            </Button>

            {/* Search Results Dropdown / Mobile Search Bar */}
            {searchOpen && (
              <div className={cn(
                "absolute top-full mt-2 bg-white border border-gray-200 rounded-lg shadow-lg overflow-hidden z-50",
                "right-0 md:left-0 md:right-auto w-[calc(100vw-2rem)] md:w-80 max-w-sm"
              )}>
                <div className="p-2 md:hidden border-b">
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <Input
                      autoFocus
                      className="pl-9 bg-gray-50 h-10"
                      placeholder="Search..."
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                    />
                    {searchQuery && (
                      <button
                        onClick={() => { setSearchQuery(""); setSearchResults([]); }}
                        className="absolute right-3 top-1/2 -translate-y-1/2"
                      >
                        <X className="w-4 h-4 text-gray-400 hover:text-gray-600" />
                      </button>
                    )}
                  </div>
                </div>

                <div className="max-h-[60vh] overflow-y-auto">
                  {searchResults.map((result, i) => (
                    <button
                      key={i}
                      className="w-full text-left px-4 py-3 hover:bg-gray-50 flex items-center gap-3 text-sm transition-colors border-b last:border-0"
                      onClick={() => navigateTo(result.href)}
                    >
                      {result.type === "alert" ? (
                        <Bell className="w-4 h-4 text-amber-500 shrink-0" />
                      ) : (
                        <ExternalLink className="w-4 h-4 text-gray-400 shrink-0" />
                      )}
                      <span className="truncate">{result.label}</span>
                      <Badge variant="secondary" className="ml-auto text-[10px] shrink-0">
                        {result.type}
                      </Badge>
                    </button>
                  ))}
                  {searchQuery && searchResults.length === 0 && (
                    <div className="p-6 text-center text-sm text-gray-400">
                      No results for &quot;{searchQuery}&quot;
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Notifications Bell */}
          <div className="relative" ref={bellRef}>
            <Button
              variant="ghost"
              size="icon"
              className="relative"
              onClick={() => {
                setBellOpen(!bellOpen);
                if (!bellOpen) fetchAlerts();
              }}
            >
              <Bell className="w-5 h-5 text-gray-500" />
              {unreadCount > 0 && (
                <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center animate-pulse">
                  {unreadCount > 9 ? "9+" : unreadCount}
                </span>
              )}
            </Button>

            {/* Alerts Dropdown */}
            {bellOpen && (
              <div className="absolute right-0 top-full mt-2 w-screen max-w-sm sm:w-96 bg-white border border-gray-200 rounded-xl shadow-xl z-50 overflow-hidden">
                <div className="flex items-center justify-between px-4 py-3 border-b bg-gray-50/50">
                  <h3 className="font-semibold text-sm text-gray-900">Notifications</h3>
                  {unreadCount > 0 && (
                    <button
                      onClick={markAllRead}
                      className="text-xs text-blue-600 hover:text-blue-700 font-medium flex items-center gap-1"
                    >
                      <CheckCheck className="w-3 h-3" /> Mark all read
                    </button>
                  )}
                </div>

                <ScrollArea className="max-h-96">
                  {loadingAlerts ? (
                    <div className="p-4 space-y-3">
                      {[...Array(3)].map((_, i) => (
                        <div key={i} className="h-12 bg-gray-100 rounded animate-pulse" />
                      ))}
                    </div>
                  ) : alerts.length === 0 ? (
                    <div className="p-8 text-center">
                      <Bell className="w-8 h-8 text-gray-200 mx-auto mb-2" />
                      <p className="text-sm text-gray-400">No notifications yet</p>
                    </div>
                  ) : (
                    <div className="divide-y divide-gray-100">
                      {alerts.slice(0, 20).map((alert) => {
                        const config = alertTypeConfig[alert.type] || alertTypeConfig.automation;
                        const Icon = config.icon;
                        return (
                          <button
                            key={alert.id}
                            className={cn(
                              "w-full text-left px-4 py-3 hover:bg-gray-50 transition-colors flex items-start gap-3",
                              !alert.isRead && "bg-blue-50/40"
                            )}
                            onClick={() => {
                              if (alert.actionUrl) navigateTo(alert.actionUrl);
                              setBellOpen(false);
                            }}
                          >
                            <div className={cn("mt-0.5 shrink-0", config.color)}>
                              <Icon className="w-4 h-4" />
                            </div>
                            <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2">
