export async function sendVoiceCallFollowUp(
  workspaceId: string,
  workspaceName: string,
  contactPhone: string,
  contactName: string,
  serviceName?: string
): Promise<{ success: boolean; callId?: string; error?: string }> {
  if (!isVapiConfigured()) {
    return { success: false, error: 'VAPI not configured' };
  }

  if (!contactPhone) {
    return { success: false, error: 'No phone number available' };
  }

  const servicePart = serviceName ? ` about your recent ${serviceName} visit` : '';
  const message = `Hi ${contactName}, this is a follow-up call from ${workspaceName || 'our business'}${servicePart}. We wanted to check if everything went well and if there's anything else we can help you with. Please call us back at your convenience. Thank you.`;

  const result = await initiateOutboundCall({
    phoneNumber: contactPhone,
    workspaceId,
    contactName,
    metadata: {
      purpose: 'follow_up',
      serviceName,
    },
  });

  if (result.success) {
    await prisma.voiceCall.create({
      data: {
        callSid: result.callId,
        direction: 'OUTBOUND',
        status: 'INITIATED',
        workspaceId,
        outcome: 'FOLLOW_UP_INITIATED',
        metadata: JSON.stringify({ purpose: 'follow_up', serviceName }),
      },
    });
  }

  return result;
}

export async function triggerVoiceAutomation(
  workspaceId: string,
  trigger: 'VOICE_REMINDER' | 'VOICE_CONFIRMATION' | 'VOICE_FOLLOW_UP',
  data: {
    contactPhone?: string;
    contactName?: string;
    serviceName?: string;
    bookingDate?: Date;
    workspaceName?: string;
  }
): Promise<{ success: boolean; error?: string }> {
  if (!data.contactPhone || !data.contactName) {
    return { success: false, error: 'Missing contact information' };
  }

  const workspaceName = data.workspaceName || 'Our Business';

  switch (trigger) {
    case 'VOICE_REMINDER':
      if (!data.bookingDate || !data.serviceName) {
        return { success: false, error: 'Missing booking information for reminder' };
      }
      return sendVoiceCallReminder(
        workspaceId,
        workspaceName,
        data.contactPhone,
        data.contactName,
        data.serviceName,
        data.bookingDate
      );

    case 'VOICE_CONFIRMATION':
      if (!data.bookingDate || !data.serviceName) {
        return { success: false, error: 'Missing booking information for confirmation' };
      }
      return sendVoiceCallConfirmation(
        workspaceId,
        workspaceName,
        data.contactPhone,
        data.contactName,
        data.serviceName,
        data.bookingDate
      );

    case 'VOICE_FOLLOW_UP':
      return sendVoiceCallFollowUp(
        workspaceId,
        workspaceName,
        data.contactPhone,
        data.contactName,
        data.serviceName
      );

    default:
      return { success: false, error: 'Unknown voice trigger' };
  }
}

import nodemailer from "nodemailer";
import { prisma } from "./prisma";

const transporter = nodemailer.createTransport({
  host: process.env.EMAIL_HOST,
  port: parseInt(process.env.EMAIL_PORT || "587"),
  auth: {
    user: process.env.EMAIL_USER,
    pass: process.env.EMAIL_PASS,
  },
});

export interface EmailOptions {
  to: string;
  subject: string;
  html: string;
  workspaceId?: string;
}

const MAX_RETRIES = 3;
const RETRY_DELAY = 1000; // 1 second

async function sleep(ms: number) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function logIntegration(type: string, status: string, to: string, message: string, error?: string, workspaceId?: string) {
  if (!workspaceId) return;

  try {
    await prisma.integrationLog.create({
      data: {
        type,
        status,
        to,
        message,
        error,
        workspaceId,
      },
    });
  } catch (e) {
    console.error("Failed to log integration:", e);
  }
}

export async function sendEmail(options: EmailOptions): Promise<boolean> {
  console.log(`Preparing to send email to: ${options.to}`);

  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    try {
      console.log(`Attempt ${attempt}/${MAX_RETRIES} connecting to ${process.env.EMAIL_HOST}...`);

      const info = await transporter.sendMail({
        from: process.env.EMAIL_FROM,
        to: options.to,
        subject: options.subject,
        html: options.html,
      });

      console.log(`✅ Email sent successfully! Message ID: ${info.messageId}`);

      await logIntegration("email", "success", options.to, options.subject, undefined, options.workspaceId);

      // In development, log the email content for debugging
      if (process.env.NODE_ENV !== "production") {
        console.log("------------------------------------------");
        console.log("EMAIL SENT (DEV MODE) - LOGGING CONTENT");
        console.log("Subject:", options.subject);
        console.log("To:", options.to);
        console.log("HTML Preview:", options.html?.substring(0, 200) + "...");
        console.log("------------------------------------------");
      }

      return true;
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`Attempt ${attempt} failed:`, message);

      if (attempt < MAX_RETRIES) {
        console.log(`Retrying in ${RETRY_DELAY * attempt}ms...`);
        await sleep(RETRY_DELAY * attempt);
      } else {
        console.error("All delivery attempts failed.");

        const errorMsg = `Failed to send "${options.subject}" to ${options.to} after ${MAX_RETRIES} attempts`;

        await logIntegration("email", "failed", options.to, options.subject, message, options.workspaceId);

        if (options.workspaceId) {
          try {
            await prisma.alert.create({
              data: {
                type: "automation",
                title: "Email Delivery Failed",
                message: errorMsg,
                actionUrl: "/inbox",
                workspaceId: options.workspaceId,
              },
            });
          } catch (e) {
            console.error("Failed to create failure alert:", e);
          }
        }

        if (process.env.NODE_ENV !== "production") {
          console.log("------------------------------------------");
          console.log("EMAIL FAILED - LOGGING CONTENT");
          console.log("Subject:", options.subject);
          console.log("To:", options.to);
          console.log("------------------------------------------");
        }
        return false;
      }
    }
  }
  return false;
}

